#!/bin/bash
# XXCENHID_APPROVE_PKG — E-Business Suite 12.2.7; generated by SQLTools 2026-11-12 11:24
# Deploys the files of manifest.txt in order, logs in logs/, stops at the first failing step.
# Usage: ./deploy.sh -e <EBS environment file> [-s <first step>] [-l] [-v] [-r] [-R]
#   -e  environment file of the TARGET application tier (EBSapps.env)
#   -s  start at this step (to resume after fixing a failure)    -l  list the steps
#   -v  validate only: check the target and report what would change, change nothing
#   -r  roll back the steps deployed (logs/done.txt), last first   -R  roll back by itself if a step fails
# Rollback: validation saves the target's current code objects, views, FNDLOAD / WFLOAD definitions and
# server files into logs/backup/ first. Tables, data, grants and XML Publisher files are not undone by
# themselves (that could lose data): logs/rollback.txt says how to undo each of them by hand.
# Every run validates first and aborts (exit 3) if a rule is broken; report: logs/validation.txt.
# Steps whose object the target already has unchanged are skipped. Exit: 0 done, 1 step failed,
# 2 usage / environment, 3 validation failed, 4 rollback failed, 5 done but objects valid before are invalid now
# (logs/invalid.txt compares the invalid objects before and after, recompiles and gives the errors).
# The APPS password is asked for (or taken from $APPS_PWD); it is never put on a command line.
# Custom schema passwords, only when APPS lacks the privileges: $SCHEMA_PWD_<SCHEMA> or asked for.
set -u
cd "$(dirname "$0")" || exit 1
HERE=$(pwd); LIB="$HERE/lib"; STAMP=$(date +%Y%m%d%H%M%S)
MODE=hotpatch
ENV_FILE=''; FIRST=1; RESUME=0; LIST=0; VALIDATE=0; ROLLBACK=0; AUTO_RB=0; NEED=' '
while getopts e:s:lvrR opt; do case $opt in e) ENV_FILE=$OPTARG;; s) FIRST=$OPTARG; RESUME=1;; l) LIST=1;;
  v) VALIDATE=1;; r) ROLLBACK=1;; R) AUTO_RB=1;; *) sed -n '2,/^set -u/p' "$0" | grep '^#'; exit 2;; esac; done
. "$LIB/common.sh"

step() {   # step N sql|loader|xdo|file FILE WHAT [command | target path]
    local n=$1 kind=$2 file=$3 what=$4; shift 4
    if [ $LIST -eq 1 ]; then printf "%3s  %-7s %-45s %s\n" "$n" "$kind" "$file" "$what"; return; fi
    [ "$n" -lt "$FIRST" ] && return
    printf "[%s/15] %-45s " "$n" "$file"
    if grep -Fxq -- "$file" logs/skip.txt 2>/dev/null; then echo 'unchanged, skipped'; return; fi
    local log="logs/$file.log" ok=0
    case $kind in
        sql)    local who=apps pw=$APPS_PWD
                if [ -n "${1:-}" ] && [ "${NEED#* $1 }" != "$NEED" ]; then
                    who=$1; local v="SCHEMA_PWD_$1"; pw=${!v}; fi
                run_sql "$file" "$log" "$who" "$pw" > /dev/null || ok=1;;
        loader) local a args=()
                for a in "$@"; do case $a in \$*) a=$(top_path "$a") || ok=1;; esac; args+=("$a"); done
                [ $ok -eq 0 ] && { run_loader "$log" "${args[@]}" > /dev/null || ok=1; };;
        xdo)    local a args=()
                for a in "$@"; do case $a in
                    '$APPS_PWD') a=$APPS_PWD;;
                    '$AD_APPS_JDBC_URL') a=${AD_APPS_JDBC_URL:-}
                        [ -n "$a" ] || { echo "AD_APPS_JDBC_URL is not set by the environment" > "$log"; ok=1; };;
                esac; args+=("$a"); done
                if [ $ok -eq 0 ]; then "${args[@]}" > "$log" 2>&1 || ok=1
                    check_log "$log" "$LOADER_ERRORS" > /dev/null || ok=1; fi;;
        file)   deploy_file "$file" "$1" > "$log" 2>&1 || ok=1;;
    esac
    if [ $ok -eq 0 ]; then echo "$n|$kind|$file|ok" >> logs/done.txt; echo ok; return; fi
    echo "$n|$kind|$file|failed" >> logs/done.txt   # may be half done: a rollback undoes it too
    echo FAILED; check_log "$log" "${SQL_ERRORS}|${LOADER_ERRORS}" || true; tail -5 "$log" | sed 's/^/    /'
    if [ $AUTO_RB -eq 1 ]; then rollback; unset APPS_PWD; exit 1; fi
    echo "Fix it, then resume with: ./deploy.sh -e $ENV_FILE -s $n"
    echo "or undo the steps deployed so far:  ./deploy.sh -e $ENV_FILE -r"
    exit 1
}

deploy_file() {   # copy into $XX_TOP/...; keep the old file; host programs get their fndcpesr link
    local dest; dest=$(top_path "$2") || return 1
    mkdir -p "$(dirname "$dest")" || return 1
    if [ -f "$dest" ]; then cp -p "$dest" "$dest.$STAMP" || return 1
        echo "kept the old file as $dest.$STAMP"; echo "@@KEPT|$dest.$STAMP"; fi
    echo "@@DEST|$dest"
    cp "$1" "$dest" || return 1
    echo "copied to $dest"
    case $dest in
        */bin/*.prog) chmod 755 "$dest"
            if [ ! -e "${dest%.prog}" ]; then ln -s "$FND_TOP/bin/fndcpesr" "${dest%.prog}" || return 1
                echo "@@LINK|${dest%.prog}"; fi
            echo "link ${dest%.prog} -> \$FND_TOP/bin/fndcpesr";;
        *.fmb) echo "NOTE: compile the form: frmcmp_batch module=$dest userid=apps output_file=${dest%.fmb}.fmx module_type=form";;
    esac
}

rb_plan() {   # FILE: 'auto' or 'manual|how to undo it by hand'
    case $1 in
        xxcenhid_notfns_list_line_seq.sql) echo 'manual|an existing sequence is never recreated; drop a new one by hand only if nothing uses it';;
        xxcenhid_notfns_list_seq.sql) echo 'manual|an existing sequence is never recreated; drop a new one by hand only if nothing uses it';;
        xxcenhid_debug_table.sql) echo 'manual|not rolled back automatically: dropping a new table or column loses data written since. Reverse the CREATE / ALTER statements in its log by hand once the data is safe; for a full undo, ask the DBA for a guaranteed restore point (or Flashback Table) before deploying';;
        xxcenhid_debug_indexes.sql) echo 'manual|drop the indexes this step created (listed in its log) if they are not wanted: DROP INDEX owner.name';;
        xxcenhid_notfns_list_lines_table.sql) echo 'manual|not rolled back automatically: dropping a new table or column loses data written since. Reverse the CREATE / ALTER statements in its log by hand once the data is safe; for a full undo, ask the DBA for a guaranteed restore point (or Flashback Table) before deploying';;
        xxcenhid_notifications_list_table.sql) echo 'manual|not rolled back automatically: dropping a new table or column loses data written since. Reverse the CREATE / ALTER statements in its log by hand once the data is safe; for a full undo, ask the DBA for a guaranteed restore point (or Flashback Table) before deploying';;
        xxcenhid_approve_pkg.pks) echo auto;;
        xxcenhid_notfns_list_line_seq_synonyms.sql) echo 'manual|drop or re-point the synonyms by hand (CREATE OR REPLACE SYNONYM ... FOR the previous object)';;
        xxcenhid_notfns_list_seq_synonyms.sql) echo 'manual|drop or re-point the synonyms by hand (CREATE OR REPLACE SYNONYM ... FOR the previous object)';;
        xxcenhid_notfns_list_lines_ev.sql) echo 'manual|follows its table: regenerate with AD_ZD_TABLE.UPGRADE after the table is put back';;
        xxcenhid_notifications_list_ev.sql) echo 'manual|follows its table: regenerate with AD_ZD_TABLE.UPGRADE after the table is put back';;
        xxcenhid_approve_pkg.pkb) echo auto;;
        lookup_type_custom_xxcenhid_eligible_item_types.ldt) echo auto;;
        concurrent_program_xxcenhid_xxcenhid_appr_get_eligible_wfs.ldt) echo auto;;
        request_group_fnd_system_administrator_reports.ldt) echo auto;;
        *) echo 'manual|no automatic undo';;
    esac
}

undo_loader() {   # FILE: upload the target's definition saved before the deployment
    local file=$1 a args=()
    case $file in
        lookup_type_custom_xxcenhid_eligible_item_types.ldt) set -- FNDLOAD apps 0 Y UPLOAD '$FND_TOP/patch/115/import/aflvmlu.lct' logs/backup/lookup_type_custom_xxcenhid_eligible_item_types.ldt -;;
        concurrent_program_xxcenhid_xxcenhid_appr_get_eligible_wfs.ldt) set -- FNDLOAD apps 0 Y UPLOAD '$FND_TOP/patch/115/import/afcpprog.lct' logs/backup/concurrent_program_xxcenhid_xxcenhid_appr_get_eligible_wfs.ldt -;;
        request_group_fnd_system_administrator_reports.ldt) set -- FNDLOAD apps 0 Y UPLOAD '$FND_TOP/patch/115/import/afcpreqg.lct' logs/backup/request_group_fnd_system_administrator_reports.ldt -;;
        *) return 1;;
    esac
    for a in "$@"; do case $a in \$*) a=$(top_path "$a") || return 1;; esac; args+=("$a"); done
    run_loader "logs/rollback/$file.log" "${args[@]}" > /dev/null
}

undo_file() {   # FILE: put back the file deploy_file replaced (its log has @@DEST / @@KEPT / @@LINK)
    local log="logs/$1.log" dest kept link
    dest=$(awk -F'|' '$1=="@@DEST"{print $2}' "$log" 2>/dev/null | tail -1)
    kept=$(awk -F'|' '$1=="@@KEPT"{print $2}' "$log" 2>/dev/null | tail -1)
    link=$(awk -F'|' '$1=="@@LINK"{print $2}' "$log" 2>/dev/null | tail -1)
    [ -n "$dest" ] || return 0
    if [ -n "$kept" ]; then cp -p "$kept" "$dest" || return 1; else rm -f "$dest" || return 1; fi
    [ -z "$link" ] || rm -f "$link"
}

rollback() {   # undo the steps of logs/done.txt, last first; steps that need a person are listed
    if [ ! -s logs/done.txt ]; then echo "Nothing to roll back: no deployment recorded in logs/done.txt"; return 0; fi
    local report=logs/rollback.txt n kind file st plan fails=0 manual=0 undone=0
    mkdir -p logs/rollback
    echo "Rolling back, last step first…"
    { echo "Rollback of $(basename "$HERE") on $(hostname) at $(date '+%Y-%m-%d %H:%M:%S')"; echo; } > "$report"
    while IFS='|' read -r n kind file st; do
        plan=$(rb_plan "$file")
        printf '  undo %-45s ' "$file"
        local res=manual why=${plan#manual|}
        if [ "$plan" = auto ]; then
            res=ok
            case $kind in
                sql)    if [ -s "logs/backup/$file.rollback.sql" ]; then
                            run_sql "logs/backup/$file.rollback.sql" "logs/rollback/$file.log" > /dev/null || res=FAILED
                        else res=manual; why="no previous version was saved (see logs/validation.txt): restore it by hand"; fi;;
                loader) if [ -s "logs/backup/$file" ]; then undo_loader "$file" || res=FAILED
                        else res=manual; why="new on the target: FNDLOAD / WFLOAD cannot delete it; disable or end-date it in the application"; fi;;
                file)   undo_file "$file" > "logs/rollback/$file.log" 2>&1 || res=FAILED;;
            esac
        fi
        case $res in
            ok)     echo 'undone'; undone=$((undone + 1)); echo "  - $file: undone" >> "$report";;
            FAILED) echo 'FAILED'; fails=$((fails + 1))
                    echo "  - $file: rollback FAILED, see logs/rollback/$file.log" >> "$report";;
            *)      echo 'by hand'; manual=$((manual + 1)); echo "  - $file: BY HAND: $why" >> "$report";;
        esac
    done < <(awk '{a[NR]=$0} END{for (i = NR; i > 0; i--) print a[i]}' logs/done.txt | awk -F'|' '!seen[$3]++')
    { echo; echo "$undone undone, $fails failed, $manual to undo by hand"; } >> "$report"
    mv logs/done.txt "logs/done.rolledback.$STAMP.txt"
    invalid_after 'after the rollback' > /dev/null; local irc=$?
    { echo; sed -n '2p' logs/invalid.txt 2>/dev/null; } >> "$report"
    echo; cat "$report"
    [ "$fails" -eq 0 ] || return 4
    [ $irc -eq 0 ] || { echo "WARNING: objects valid before the deployment are still invalid: see logs/invalid.txt"; return 5; }
}

sql_rows() {   # SQL: rows of a query as APPS ("a|b|c" lines only)
    { printf 'connect apps/"%s"\n' "$APPS_PWD"
      printf 'set heading off feedback off pagesize 0 linesize 4000 trimspool on tab off\n%s\nexit\n' "$1"; } \
        | sqlplus -s /nolog 2>&1
}

invalid_snapshot() {   # FILE: "owner|type|name" of every invalid object (sorted); 1 if it could not be read
    local out
    out=$(sql_rows "SELECT owner || '|' || object_type || '|' || object_name FROM dba_objects WHERE status = 'INVALID' AND object_name NOT LIKE 'BIN\$%';")
    echo "$out" > logs/invalid.log
    case $out in *ORA-*|*SP2-*) return 1;; esac
    echo "$out" | grep -E '^[^|]+\|[^|]+\|[^|]+$' | sort -u > "$1"
}

invalid_before() {   # the invalid objects before the deployment (kept when resuming)
    if [ $RESUME -eq 1 ] && [ -f logs/invalid.before.txt ]; then return 0; fi
    if invalid_snapshot logs/invalid.before.txt; then
        echo "Invalid objects on the target before deploying: $(wc -l < logs/invalid.before.txt | tr -d ' ')"
    else
        rm -f logs/invalid.before.txt; echo "WARNING: could not list invalid objects (logs/invalid.log)"
    fi
}

invalid_after() {   # WHEN: compare with before, recompile what became invalid, report; 5 if any are still invalid
    local before=logs/invalid.before.txt after=logs/invalid.after.txt rep=logs/invalid.txt
    [ -f "$before" ] || { echo "No list of invalid objects from before the deployment: not compared"; return 0; }
    invalid_snapshot "$after" || { echo "WARNING: could not list invalid objects (logs/invalid.log)"; return 0; }
    comm -13 "$before" "$after" > logs/invalid.new.txt
    if [ -s logs/invalid.new.txt ]; then
        echo "Recompiling $(wc -l < logs/invalid.new.txt | tr -d ' ') object(s) that became invalid…"
        awk -F'|' '{ o = "\"" $1 "\".\"" $3 "\""
            if ($2 == "PACKAGE BODY") s = "ALTER PACKAGE " o " COMPILE BODY;"
            else if ($2 == "TYPE BODY") s = "ALTER TYPE " o " COMPILE BODY;"
            else if ($2 == "SYNONYM" && $1 == "PUBLIC") s = "ALTER PUBLIC SYNONYM \"" $3 "\" COMPILE;"
            else if ($2 ~ /^(PACKAGE|TYPE|PROCEDURE|FUNCTION|TRIGGER|VIEW|SYNONYM|MATERIALIZED VIEW)$/) s = "ALTER " $2 " " o " COMPILE;"
            else next
            print s; again = again s "\n" } END { printf "%s", again }' logs/invalid.new.txt > logs/recompile.sql
        run_sql logs/recompile.sql logs/recompile.log > /dev/null || true
        invalid_snapshot "$after" || true
    fi
    comm -13 "$before" "$after" > logs/invalid.still.txt
    comm -23 logs/invalid.new.txt logs/invalid.still.txt > logs/invalid.fixed.txt
    comm -23 "$before" "$after" > logs/invalid.valid.txt
    : > logs/invalid.errors.txt
    if [ -s logs/invalid.still.txt ]; then
        sql_rows "SELECT e.owner || '|' || e.type || '|' || e.name || '|line ' || e.line || ': ' || REPLACE(e.text, CHR(10), ' ') FROM dba_errors e WHERE e.attribute = 'ERROR' AND (e.owner, e.name, e.type) IN (SELECT owner, object_name, object_type FROM dba_objects WHERE status = 'INVALID') ORDER BY e.owner, e.name, e.type, e.sequence;" \
            | awk -F'|' 'NR == FNR { want[$1 "|" $2 "|" $3] = 1; next }
                         want[$1 "|" $2 "|" $3] && n[$1 "|" $2 "|" $3]++ < 5' logs/invalid.still.txt - > logs/invalid.errors.txt
    fi
    local nb na nn ns
    nb=$(wc -l < "$before" | tr -d ' '); na=$(wc -l < "$after" | tr -d ' ')
    nn=$(wc -l < logs/invalid.new.txt | tr -d ' '); ns=$(wc -l < logs/invalid.still.txt | tr -d ' ')
    {
        echo "Invalid objects $1 on $(hostname) at $(date '+%Y-%m-%d %H:%M:%S')"
        echo "Before: $nb   After: $na   Became invalid: $nn   Still invalid after recompiling: $ns"
        echo; echo "Became invalid (cascading effect of the changes), fixed by recompiling:"
        if [ -s logs/invalid.fixed.txt ]; then sed 's/|/ /g; s/^/  - /' logs/invalid.fixed.txt; else echo "  none"; fi
        echo; echo "STILL INVALID (were valid before):"
        if [ -s logs/invalid.still.txt ]; then
            while IFS= read -r k; do echo "  - ${k//|/ }"
                grep -F -- "$k|" logs/invalid.errors.txt | cut -d'|' -f4- | sed 's/^/      /'; done < logs/invalid.still.txt
        else echo "  none"; fi
        echo; echo "Valid again (were invalid before):"
        if [ -s logs/invalid.valid.txt ]; then sed 's/|/ /g; s/^/  - /' logs/invalid.valid.txt; else echo "  none"; fi
        echo; echo "Invalid before and still invalid (not caused by this run): $(comm -12 "$before" "$after" | wc -l | tr -d ' ')"
        if [ "$ns" -gt 0 ]; then
            echo; echo "What to do:"
            echo "  These objects depend on something this run changed: a package spec, type, view, table column,"
            echo "  grant or synonym. The errors above say what they no longer find (a removed or renamed procedure,"
            echo "  parameter, column or type; a missing privilege)."
            echo "  1. Fix the dependent object (change it on the source and add it to the bundle), or make the"
            echo "     change compatible again (keep the old procedure / parameter / column), or add the missing grant."
            echo "  2. Recompile: ALTER <type> <owner>.<name> COMPILE (BODY); for many, adadmin 'Compile APPS schema'"
            echo "     or the DBA's utlrp.sql."
            echo "  3. If it cannot be fixed now: ./deploy.sh -e <environment file> -r undoes the deployment."
        fi
    } > "$rep"
    echo "Invalid objects: before $nb, after $na; became invalid $nn, still invalid $ns (logs/invalid.txt)"
    if [ "$ns" -gt 0 ]; then
        echo "WARNING: $ns object(s) valid before are invalid now:"
        sed 's/|/ /g; s/^/    /' logs/invalid.still.txt | head -20
        return 5
    fi
    return 0
}

done_step() { [ -f logs/done.txt ] && awk -F'|' -v f="$1" '$3==f{x=1} END{exit !x}' logs/done.txt; }

backup() {   # backup FILE FNDLOAD|WFLOAD ...: download the target's copy, skip the upload if the same
    local file=$1; shift
    done_step "$file" && return 0     # resuming: keep what the target had before the deployment
    local a args=()
    for a in "$@"; do case $a in \$*) a=$(top_path "$a") || return 0;; esac; args+=("$a"); done
    if run_loader "logs/backup/$file.log" "${args[@]}" > /dev/null 2>&1 && [ -s "logs/backup/$file" ]; then
        if same_aol "$file" "logs/backup/$file"; then
            echo "@@SKIP|$file|the target has the same definition (backup in logs/backup)||" >> "$VLOG"
        else
            echo "@@PLAN|$file|upload: differs from the target (backup in logs/backup/$file)||" >> "$VLOG"
        fi
    else
        echo "@@PLAN|$file|upload: new on the target (nothing to back up)||" >> "$VLOG"
    fi
}

validate() {
    VLOG=logs/validation.log; local report=logs/validation.txt f owner v pw out
    mkdir -p logs/backup; : > logs/skip.txt
    echo "Validating on the target…"
    { printf 'connect apps/"%s"\n' "$APPS_PWD"; printf '@"lib/validate.sql"\nexit\n'; } | sqlplus -s /nolog > "$VLOG" 2>&1
    grep -v '^@@' "$VLOG" | grep -E "$SQL_ERRORS" | sed 's/^/@@FAIL|lib\/validate.sql|SQL error|/;s/$/|fix the error and validate again/' >> "$VLOG"
    for f in xxcenhid_notfns_list_line_seq.sql xxcenhid_notfns_list_seq.sql xxcenhid_debug_table.sql xxcenhid_debug_indexes.sql xxcenhid_notfns_list_lines_table.sql xxcenhid_notifications_list_table.sql xxcenhid_approve_pkg.pks xxcenhid_notfns_list_line_seq_synonyms.sql xxcenhid_notfns_list_seq_synonyms.sql xxcenhid_notfns_list_lines_ev.sql xxcenhid_notifications_list_ev.sql xxcenhid_approve_pkg.pkb lookup_type_custom_xxcenhid_eligible_item_types.ldt concurrent_program_xxcenhid_xxcenhid_appr_get_eligible_wfs.ldt request_group_fnd_system_administrator_reports.ldt; do
        [ -f "$f" ] || echo "@@FAIL|$f|file missing|not in the bundle folder|run download.sh on the source (or Download AOL Files) and copy it in" >> "$VLOG"
    done
    backup lookup_type_custom_xxcenhid_eligible_item_types.ldt FNDLOAD apps 0 Y DOWNLOAD '$FND_TOP/patch/115/import/aflvmlu.lct' logs/backup/lookup_type_custom_xxcenhid_eligible_item_types.ldt FND_LOOKUP_TYPE APPLICATION_SHORT_NAME=CUSTOM LOOKUP_TYPE=XXCENHID_ELIGIBLE_ITEM_TYPES
    backup concurrent_program_xxcenhid_xxcenhid_appr_get_eligible_wfs.ldt FNDLOAD apps 0 Y DOWNLOAD '$FND_TOP/patch/115/import/afcpprog.lct' logs/backup/concurrent_program_xxcenhid_xxcenhid_appr_get_eligible_wfs.ldt PROGRAM APPLICATION_SHORT_NAME=XXCENHID CONCURRENT_PROGRAM_NAME=XXCENHID_APPR_GET_ELIGIBLE_WFS
    backup request_group_fnd_system_administrator_reports.ldt FNDLOAD apps 0 Y DOWNLOAD '$FND_TOP/patch/115/import/afcpreqg.lct' logs/backup/request_group_fnd_system_administrator_reports.ldt REQUEST_GROUP APPLICATION_SHORT_NAME=FND 'REQUEST_GROUP_NAME=System Administrator Reports'
    mkdir -p logs/backup/tmp; rm -f logs/backup/tmp/*
    { printf 'connect apps/"%s"\n' "$APPS_PWD"; printf '@"lib/backup.sql"\nexit\n'; } | sqlplus -s /nolog > logs/backup/backup.log 2>&1
    for f in logs/backup/tmp/*.rollback.sql; do [ -e "$f" ] || continue
        b=$(basename "$f" .rollback.sql)
        if done_step "$b"; then rm -f "$f"; continue; fi
        if grep -Eq "$SQL_ERRORS" "$f"; then rm -f "$f" "logs/backup/$b.rollback.sql"
            echo "@@WARN|$b|no rollback copy|$(grep -Eo 'ORA-[0-9]+[^|]*' "$f" 2>/dev/null | head -1)|" >> "$VLOG"
        else mv -f "$f" logs/backup/; fi
    done
    for owner in $(sed -n 's/^@@NEEDPWD|\([^|]*\)|.*/\1/p' "$VLOG" | sort -u); do
        v="SCHEMA_PWD_$owner"
        if [ -z "${!v:-}" ]; then
            if [ -t 0 ]; then read -rsp "Password of $owner (APPS cannot change its tables): " pw; echo
                printf -v "$v" '%s' "$pw"; export "${v?}"
            else
                echo "@@FAIL|schema $owner|schema password needed|APPS lacks CREATE / ALTER ANY TABLE and \$$v is not set|set $v from the pipeline's secrets, or grant those privileges to APPS" >> "$VLOG"
                continue
            fi
        fi
        out=$( { printf 'connect %s/"%s"\n' "$owner" "${!v}"; echo exit; } | sqlplus -s /nolog 2>&1 )
        case $out in *ORA-*|*SP2-*) echo "@@FAIL|schema $owner|schema login failed|$(echo "$out" | grep -Eo 'ORA-[0-9]+[^|]*' | head -1)|check $v" >> "$VLOG";; *) NEED="$NEED$owner ";; esac
    done
    sed -n 's/^@@SKIP|\([^|]*\)|.*/\1/p' "$VLOG" >> logs/skip.txt
    if [ -f lib/checksums.txt ]; then
        while read -r sum size f; do [ -f "$f" ] || continue
            [ "$(cksum < "$f" | awk '{print $1" "$2}')" = "$sum $size" ] && continue
            echo "@@WARN|$f|edited after generation|deployed even if the target looks unchanged|" >> "$VLOG"
            echo "$f"; done < lib/checksums.txt > logs/edited.txt
        grep -vFxf logs/edited.txt logs/skip.txt > logs/skip.tmp; mv logs/skip.tmp logs/skip.txt
    fi
    grep '^@@SKIPIF|' "$VLOG" | while IFS='|' read -r _k f dep _r; do
        grep -Fxq -- "$dep" logs/skip.txt && echo "$f"; done >> logs/skip.txt
    local fails; fails=$(grep -c '^@@FAIL|' "$VLOG")
    {
        echo "Validation of $(basename "$HERE") on $(hostname) at $(date '+%Y-%m-%d %H:%M:%S')"
        if [ "$fails" -gt 0 ]; then echo "Result: FAILED, $fails problem(s): nothing was changed"; else echo 'Result: PASSED'; fi
        echo; echo 'Problems (must be fixed before deploying):'
        awk -F'|' '$1=="@@FAIL"{printf "  - %s: %s\n      %s\n      fix: %s\n", $2, $3, $4, $5; n++} END{if(!n) print "  none"}' "$VLOG"
        echo; echo 'Warnings:'
        awk -F'|' '$1=="@@WARN"{printf "  - %s: %s: %s\n", $2, $3, $4; n++} END{if(!n) print "  none"}' "$VLOG"
        echo; echo 'Changes the deployment makes:'
        awk -F'|' '$1=="@@PLAN"{printf "  - %s: %s\n", $2, $3; n++} END{if(!n) print "  none"}' "$VLOG"
        echo; echo 'Unchanged on the target (skipped):'
        if [ -s logs/skip.txt ]; then sed 's/^/  - /' logs/skip.txt; else echo '  none'; fi
        echo; echo 'Rollback (./deploy.sh -r; -R does it by itself when a step fails):'
        for f in xxcenhid_notfns_list_line_seq.sql xxcenhid_notfns_list_seq.sql xxcenhid_debug_table.sql xxcenhid_debug_indexes.sql xxcenhid_notfns_list_lines_table.sql xxcenhid_notifications_list_table.sql xxcenhid_approve_pkg.pks xxcenhid_notfns_list_line_seq_synonyms.sql xxcenhid_notfns_list_seq_synonyms.sql xxcenhid_notfns_list_lines_ev.sql xxcenhid_notifications_list_ev.sql xxcenhid_approve_pkg.pkb lookup_type_custom_xxcenhid_eligible_item_types.ldt concurrent_program_xxcenhid_xxcenhid_appr_get_eligible_wfs.ldt request_group_fnd_system_administrator_reports.ldt; do grep -Fxq -- "$f" logs/skip.txt && continue
            p=$(rb_plan "$f"); if [ "$p" = auto ]; then echo "  - $f: automatic"; else echo "  - $f: BY HAND: ${p#manual|}"; fi
        done
    } > "$report"
    cat "$report"
    if [ "${GITHUB_ACTIONS:-}" = true ]; then
        awk -F'|' '$1=="@@FAIL"{printf "::error title=%s::%s: %s (fix: %s)\n", $3, $2, $4, $5}' "$VLOG"
    fi
    [ "$fails" -eq 0 ]
}

if [ $LIST -eq 0 ]; then
    [ -n "$ENV_FILE" ] || { echo "Give the environment file of this application tier: ./deploy.sh -e <file>"; exit 2; }
    . "$ENV_FILE" run >/dev/null 2>&1 </dev/null || { echo "Could not source $ENV_FILE"; exit 2; }
    [ -n "${APPL_TOP:-}" ] || { echo "$ENV_FILE did not set APPL_TOP"; exit 2; }
    if [ -z "${APPS_PWD:-}" ]; then
        [ -t 0 ] || { echo "APPS_PWD is not set and there is no terminal to ask for it"; exit 2; }
        read -rsp 'APPS password: ' APPS_PWD; echo
    fi
    export APPS_PWD
    mkdir -p logs
    check=$( { printf 'connect apps/"%s"\n' "$APPS_PWD"
        printf 'set heading off feedback off pagesize 0\n'
        printf "select 'EDITION='||sys_context('userenv','current_edition_name')||' RUN='||ad_zd.get_edition('RUN')||' PATCH='||ad_zd.get_edition('PATCH') from dual;\n"
        echo exit; } | sqlplus -s /nolog 2>&1 )
    case $check in *ORA-*|*SP2-*) echo "APPS login failed:"; echo "$check" | grep -E 'ORA-|SP2-'; exit 2;; esac
    echo "Connected: $(echo "$check" | grep EDITION=)"
    echo "Hotpatch: deploying into the run edition while the system is online"
    warn_no_expect
    if [ $ROLLBACK -eq 1 ]; then rollback; rc=$?; unset APPS_PWD; exit $rc; fi
    if [ $VALIDATE -eq 0 ] && [ $RESUME -eq 0 ] && grep -q '|failed$' logs/done.txt 2>/dev/null; then
        echo "The last deployment stopped at step $(grep '|failed$' logs/done.txt | tail -1 | cut -d'|' -f1)."
        echo "Resume it with -s <step>, or undo it first with -r; starting over would overwrite its backups."
        exit 2
    fi
    if [ $VALIDATE -eq 0 ] && [ $RESUME -eq 0 ] && [ -s logs/done.txt ]; then mv logs/done.txt "logs/done.$STAMP.txt"; fi
    validate || exit 3
    invalid_before
    if [ $VALIDATE -eq 1 ]; then unset APPS_PWD; echo "Validation passed; nothing was changed"; exit 0; fi
fi

step 1 sql xxcenhid_notfns_list_line_seq.sql sequence
step 2 sql xxcenhid_notfns_list_seq.sql sequence
step 3 sql xxcenhid_debug_table.sql 'table (create or alter)'
step 4 sql xxcenhid_debug_indexes.sql 'indexes (those not there yet)'
step 5 sql xxcenhid_notfns_list_lines_table.sql 'table (create or alter)' XXCENHID
step 6 sql xxcenhid_notifications_list_table.sql 'table (create or alter)' XXCENHID
step 7 sql xxcenhid_approve_pkg.pks 'package spec'
step 8 sql xxcenhid_notfns_list_line_seq_synonyms.sql synonyms
step 9 sql xxcenhid_notfns_list_seq_synonyms.sql synonyms
step 10 sql xxcenhid_notfns_list_lines_ev.sql 'editioning view and APPS synonym'
step 11 sql xxcenhid_notifications_list_ev.sql 'editioning view and APPS synonym'
step 12 sql xxcenhid_approve_pkg.pkb 'package body'
step 13 loader lookup_type_custom_xxcenhid_eligible_item_types.ldt 'Lookup type' FNDLOAD apps 0 Y UPLOAD '$FND_TOP/patch/115/import/aflvmlu.lct' lookup_type_custom_xxcenhid_eligible_item_types.ldt -
step 14 loader concurrent_program_xxcenhid_xxcenhid_appr_get_eligible_wfs.ldt 'Concurrent program' FNDLOAD apps 0 Y UPLOAD '$FND_TOP/patch/115/import/afcpprog.lct' concurrent_program_xxcenhid_xxcenhid_appr_get_eligible_wfs.ldt -
step 15 loader request_group_fnd_system_administrator_reports.ldt 'Request group' FNDLOAD apps 0 Y UPLOAD '$FND_TOP/patch/115/import/afcpreqg.lct' request_group_fnd_system_administrator_reports.ldt -

[ $LIST -eq 1 ] && exit 0
echo "All 15 steps done; logs are in $HERE/logs"
invalid_after 'before and after the deployment'; IRC=$?
unset APPS_PWD
exit $IRC
